--[[ Macr0 plain bootstrap (prepended, NOT obfuscated).
     Runs in the REAL environment. The obfuscated body loads the theme and
     installs the cursor from INSIDE Luraph's VM, whose loadstring/_G do not
     reach the real globals -- so the theme never applies and the cursor guard
     (which lives in _G.MACR0_UI) is never visible. This re-does both out here
     with the real loadstring, once a live window exists. ]]
task.spawn(function()
    local REPO = "https://raw.githubusercontent.com/Macro002/Macr0-Hub-Scripts-Public/main/"
    -- Wait for a WindUI whose ScreenGui is actually parented (live). The
    -- parented check matters at the loader->freedraw handoff: _G.WindUI still
    -- points at the loader's destroyed window until freedraw sets its own.
    local W
    for _ = 1, 600 do
        local c = _G.WindUI or (getgenv and getgenv().WindUI) or (shared and shared.WindUI)
        if c and c.ScreenGui and c.ScreenGui.Parent then W = c break end
        task.wait(0.05)
    end
    if not W then return end
    -- Real loadstring: theme.lua registers "Macr0" and sets _G.MACR0_UI here,
    -- in the real environment, then SetTheme applies it to the live window.
    pcall(function() loadstring(game:HttpGet(REPO .. "theme.lua"))() end)
    pcall(function() if W.SetTheme then W:SetTheme("Macr0") end end)
    if _G.MACR0_UI then
        pcall(function() _G.MACR0_UI.pinOnTop(W) end)
        pcall(function() _G.MACR0_UI.cursorGuard(W) end)
    end
end)

